import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, k = map(int, input[ptr:ptr+2])
        ptr += 2
        a = list(map(int, input[ptr:ptr+n]))
        ptr += n
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr:ptr+2])
            ptr += 2
            adj[u].append(v)
            adj[v].append(u)

        total_xor = 0
        for num in a:
            total_xor ^= num

        if k >= n:
            print("YES")
            continue

        if total_xor == 0:
            print("YES")
            continue

        possible = False
        for m in range(1, k):
            if (total_xor ^ (total_xor ^ total_xor)) == 0:
                possible = True
                break
            if (total_xor ^ (total_xor ^ total_xor)) != 0:
                continue

        if not possible:
            print("NO")
            continue

        xor_set = set()
        xor_set.add(0)
        for num in a:
            new_xor = set()
            for x in xor_set:
                new_xor.add(x ^ num)
            xor_set.update(new_xor)

        if total_xor in xor_set:
            print("YES")
        else:
            print("NO")

def main():
    solve()

if __name__ == "__main__":
    main()
